package com.clavis.reader;import java.nio.channels.*;import java.nio.file.*;import java.util.*;public class QuickTimeChapterChecks {public static void main(String[] args)throws Exception{int n=0;for(String p:args){try(FileChannel c=FileChannel.open(Path.of(p))){List<EmbeddedChapters.Marker> m=EmbeddedChapters.read(c);if(m.size()!=2||m.get(1).time!=60000||!m.get(1).title.equals("Chapter Two"))throw new AssertionError(p);n+=3;}}System.out.println(n+" QuickTime chapter checks passed");}}